// Источник: web-тест .qa/e2e/tests/tehilim/th-01-chapter-reading-screen.spec.ts, план .qa/e2e/specs/tehilim.md, кейс .qa/tests/tehilim/TH-01-chapter-reading-screen.md
// Тикеты #6a86f7da (мокап экрана чтения, done), #6a86f7fca7ea (ספריית תהילים, проверено 07.10). Опора: F-52 AC1/AC3, S-25 AC3/AC4, Figma 641:2633 / 454:5200, реджект 29.09 (полосы перехода нет).
// В приложении «המשך לשיתוף» открывает СИСТЕМНОЕ окно «Поделиться» — не автоматизируем: проверяем своё окно (текст + ссылка) и «ביטול».
// «סיים קריאה» здесь НЕ нажимаем (пишет данные) — это TH-03 (@data).
import { $, driver, expect } from '@wdio/globals';
import { byText, byTextContains, tapText, tapLabel, expectVisibleText, expectTextContains, scrollToText } from '../../helpers/ui.ts';
import { goTab, hasDeepLinks, openRoute, TABS } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const SHARE_TEXT = 'קראתי עכשיו תהילים ע״ב (לשלמה אלהים משפטיך). מצטרפים לקרוא גם?';
const SHARE_LINK = 'https://zichui-harabim.expo.app/tehilim/72';

/** Открыть פרק ע״ב: deep link, иначе «תהילים» → поиск «72» → карточка. */
async function openChapter72() {
  if (hasDeepLinks()) {
    await openRoute('/tehilim/72');
  } else {
    await goTab('תהילים');
    const search = await (driver.isAndroid
      ? $('android=new UiSelector().className("android.widget.EditText")')
      : $('-ios class chain:**/XCUIElementTypeTextField'));
    await search.waitForDisplayed();
    await search.setValue('72');
    await (await byTextContains('לשלמה')).click();
  }
  await (await byText('תהילים ע״ב')).waitForDisplayed({ timeout: 20000 });
}

describe('Чтение תהילים', () => {
  afterEach(async () => { await toHome(); });

  it('TH-01 Экран פרק תהילים — без полосы перехода; «סיים קריאה», «האזן להקראה», ⓘ, «חזק את חברך», нижняя навигация #6a86f7da @prod-safe', async () => {
    // 1–2. Открыть פרק ע״ב.
    await openChapter72();
    await expectVisibleText('תהילים ע״ב');
    await expectVisibleText('לשלמה אלהים משפטיך');
    // Текст с огласовками: сравнение после normalize('NFC') (порядок огласовок может отличаться от литерала).
    const src = (await driver.getPageSource()).normalize('NFC');
    expect(src.includes('לִשְׁלֹמֹה'.normalize('NFC'))).toBe(true);
    await expect(byText('פרק ע״א')).not.toBeDisplayed();       // нет полосы перехода (реджект 29.09)
    await expect(byText('פרק ע״ג')).not.toBeDisplayed();

    // Под текстом: «סיים קריאה» (НЕ нажимать), «האזן להקראה» + «השמע» неактивна + «אין הקראה לפרק הזה», «חזק את חברך».
    await scrollToText('חזק את חברך', 15);
    await expectVisibleText('סיים קריאה');
    await expectVisibleText('האזן להקראה');
    await expect(byText('השמע')).toBeDisabled();
    await expectTextContains('אין הקראה לפרק הזה');
    await expectTextContains('מקור: Sefaria.org');

    // 3. ⓘ «הסבר על הפרק» → окно «על תהילים ע״ב» → «סגירה והמשך בקריאה».
    await tapLabel('הסבר על הפרק');
    await expectVisibleText('על תהילים ע״ב');
    await expectTextContains('עדיין אין הסבר מאושר');
    await tapText('סגירה והמשך בקריאה');
    await expect(byText('על תהילים ע״ב')).not.toBeDisplayed();

    // 4. «חזק את חברך» → своё окно: точный текст + ссылка, «ביטול» и «המשך לשיתוף» (S-25 AC4). Системный share — не открываем.
    await tapText('חזק את חברך');
    await expectTextContains(SHARE_TEXT);
    await expectTextContains(SHARE_LINK);
    await expectVisibleText('המשך לשיתוף');
    await tapText('ביטול');
    await expect(byTextContains(SHARE_TEXT)).not.toBeDisplayed();
    await expectVisibleText('תהילים ע״ב');                       // остались на экране чтения

    // 5. Нижняя навигация: «תהילים», «תפילות», «בית», «המסע שלי», «ברכות».
    for (const tab of TABS) await expectVisibleText(tab);
  });
});
